#pragma once

#include "cry_guid_text.h"

#include "shared/features/player/player_buff.h"

#include <cstddef>
#include <cstdint>
#include <string_view>
#include <vector>

namespace KCDC::Shared::Game {
    /**
     * One row of the game's buff tables: the set of status effects the mod
     * can put on a soul, carrying only the columns replication and scripting
     * need.
     *
     * Generated by `tools/generate_buff_catalog.py` rather than read from the
     * running game, because the server has no game module to read it from and
     * both sides must agree on the name-to-GUID spelling.
     */
    struct BuffEntry {
        std::string_view name; // buff_name, e.g. "food_poison"
        std::string_view guid; // canonical 8-4-4-4-12, lower case

        // The same GUID as the bytes the engine uses. Carried rather than parsed
        // on demand: `FindBuffById` is the lookup the wire drives.
        RPC::BuffId id;

        std::string_view uiName; // buff_ui_name, empty for the many rows with none

        std::uint8_t classId;     // buff_class_id
        std::int8_t aiTag;        // buff_ai_tag_id, -1 for none
        std::int8_t family;       // buff_family_id, -1 for none
        std::uint8_t exclusivity; // buff_exclusivity_id
        std::uint8_t uiType;      // buff_ui_type_id, 0 for none
        std::uint8_t lifetime;    // buff_lifetime_id: 0 ShortTerm, 1 LongTerm
        bool persistent;          // is_persistent

        /**
         * Whether this row's duration is written in game seconds.
         *
         * Six implementations scale the frame delta by the world-time ratio
         * before adding it; every other one counts real seconds. The
         * distinction is invisible in the table -- `well_rested` and
         * `dlc2_bed_sleep_well_rested` both say `5760` and are a factor of
         * fifteen apart -- so the generator carries a mined list.
         */
        bool worldTime;

        /** In the row's own unit. Negative means indefinite. */
        float duration;
    };

    /** `buff_class_id` values, from `buff_class.xml`. */
    namespace BuffClass {
        inline constexpr std::uint8_t kTestingStat     = 0;
        inline constexpr std::uint8_t kSystem          = 1;
        inline constexpr std::uint8_t kWeaponSkill     = 2;
        inline constexpr std::uint8_t kTestingCombat   = 3;
        inline constexpr std::uint8_t kPerk            = 4;
        inline constexpr std::uint8_t kInjury          = 5;
        inline constexpr std::uint8_t kHeal            = 6;
        inline constexpr std::uint8_t kPoison          = 7;
        inline constexpr std::uint8_t kPerception      = 8;
        inline constexpr std::uint8_t kOvereat         = 9;
        inline constexpr std::uint8_t kAlcohol         = 10;
        inline constexpr std::uint8_t kItem            = 12;
        inline constexpr std::uint8_t kPotion          = 13;
        inline constexpr std::uint8_t kFoodPoison      = 14;
        inline constexpr std::uint8_t kScriptSystem    = 15;
        inline constexpr std::uint8_t kUnconsciousness = 16;
        inline constexpr std::uint8_t kHangover        = 17;
        inline constexpr std::uint8_t kSatisfaction    = 18;
        inline constexpr std::uint8_t kPerfume         = 19;
        inline constexpr std::uint8_t kPunishment      = 20;
        inline constexpr std::uint8_t kForcedDrunk     = 21;
        inline constexpr std::uint8_t kPlague          = 22;
        inline constexpr std::uint8_t kCount           = 23;

        /** A class's bit in a claim or report mask. Ids run 0..22, so a mask is one word. */
        inline constexpr std::uint32_t Bit(std::uint8_t classId) {
            return classId < 32 ? 1U << classId : 0U;
        }

        /** The names the scripting API spells the classes with. Id 11 names nothing, hence a table rather than a range. */
        inline constexpr std::string_view kNames[kCount] = {"testingStat", "system", "weaponSkill", "testingCombat", "perk", "injury", "heal", "poison", "perception", "overeat", "alcohol", "", "item", "potion", "foodPoison", "scriptSystem", "unconsciousness", "hangover",
            "satisfaction", "perfume", "punishment", "forcedDrunkenness", "plague"};

        /** Empty for an id no class uses. */
        inline constexpr std::string_view Name(std::uint8_t classId) {
            return classId < kCount ? kNames[classId] : std::string_view();
        }

        /** The id a class name refers to, or -1. */
        inline constexpr int Find(std::string_view name) {
            for (std::uint8_t id = 0; id < kCount; ++id) {
                if (!kNames[id].empty() && kNames[id] == name) {
                    return id;
                }
            }
            return -1;
        }
    } // namespace BuffClass

    /**
     * The buff classes an owner reports without being asked: the ones carrying
     * state no observer can derive. The rest are derived instead -- perks
     * shadow the perk list, item buffs follow equipment, and the
     * context-checked constants are predicates every client re-evaluates.
     *
     * Shared rather than client-side because the server reconciles reports
     * against the orders it sent, so it has to know which can come back.
     */
    inline constexpr std::uint32_t kStatefulBuffClasses = BuffClass::Bit(BuffClass::kInjury) | BuffClass::Bit(BuffClass::kHeal) | BuffClass::Bit(BuffClass::kPoison) | BuffClass::Bit(BuffClass::kPerception) | BuffClass::Bit(BuffClass::kOvereat)
                                                          | BuffClass::Bit(BuffClass::kAlcohol) | BuffClass::Bit(BuffClass::kPotion) | BuffClass::Bit(BuffClass::kFoodPoison) | BuffClass::Bit(BuffClass::kUnconsciousness) | BuffClass::Bit(BuffClass::kHangover)
                                                          | BuffClass::Bit(BuffClass::kSatisfaction) | BuffClass::Bit(BuffClass::kPerfume) | BuffClass::Bit(BuffClass::kPunishment) | BuffClass::Bit(BuffClass::kForcedDrunk) | BuffClass::Bit(BuffClass::kPlague);

    /**
     * The same set read the other way round. Claiming a class outside it does
     * not move a decision to the server -- `perk` would strip every perk on
     * the local body, `system` carries encumbrance among 147 others -- so the
     * binding refuses those by name.
     */
    inline constexpr bool IsClaimableBuffClass(std::uint8_t classId) {
        return (kStatefulBuffClasses & BuffClass::Bit(classId)) != 0;
    }

    /** Game seconds per real second. The engine reads its own copy from the RPG config. */
    inline constexpr float kWorldTimeRatio = 15.0F;

    /** Every buff definition the game ships, sorted by name. */
    extern const std::vector<BuffEntry> g_Buffs;

    /** `buff_ai_tag.xml` in id order, so the index is the native tag id. */
    extern const std::vector<std::string_view> g_BuffAiTags;

    const BuffEntry *FindCustomBuff(std::string_view query);
    const BuffEntry *FindCustomBuffById(const RPC::BuffId &id);

    inline const BuffEntry *FindBuffByGuid(std::string_view guid) {
        for (const auto &buff : g_Buffs) {
            if (buff.guid == guid) {
                return &buff;
            }
        }
        return FindCustomBuff(guid);
    }

    inline const BuffEntry *FindBuffByName(std::string_view name) {
        for (const auto &buff : g_Buffs) {
            if (buff.name == name) {
                return &buff;
            }
        }
        return FindCustomBuff(name);
    }

    /** A GUID or an exact name, the same double spelling item queries take. */
    inline const BuffEntry *ResolveBuff(std::string_view query) {
        const BuffEntry *byGuid = FindBuffByGuid(query);
        return byGuid != nullptr ? byGuid : FindBuffByName(query);
    }

    /** The native id of an AI tag name, or -1 for a name no row uses. */
    inline int FindBuffAiTag(std::string_view name) {
        for (std::size_t index = 0; index < g_BuffAiTags.size(); ++index) {
            if (g_BuffAiTags[index] == name) {
                return static_cast<int>(index);
            }
        }
        return -1;
    }

    /** A row's duration in real seconds, whichever unit it was written in. Indefinite stays negative. */
    inline float BuffDurationSeconds(const BuffEntry &buff) {
        if (buff.duration < 0.0F) {
            return -1.0F;
        }
        return buff.worldTime ? buff.duration / kWorldTimeRatio : buff.duration;
    }

    /** A malformed GUID gives `{0, 0}`, which reads as invalid everywhere it goes. */
    inline constexpr RPC::BuffId BuffIdFromGuid(std::string_view guid) {
        RPC::BuffId buff;
        CryGuidFromText(guid, buff.low, buff.high);
        return buff;
    }

    // Pinned on `food_poison` as the buff table writes it, so a change that
    // breaks the encoding fails to compile. The generator spells every row's
    // `id` through this same conversion.
    static_assert(BuffIdFromGuid("04218e40-e756-476b-914e-03d67a24e733") == RPC::BuffId {0x476BE75604218E40ULL, 0x33E7247AD6034E91ULL}, "Buff GUID encoding does not match the game's own parser");
    static_assert(BuffIdFromGuid("not-a-guid") == RPC::BuffId {}, "A malformed buff GUID must not produce a usable definition");

    inline RPC::BuffId BuffIdOf(const BuffEntry &buff) {
        return buff.id;
    }

    /** Null for a definition this build's tables do not carry. */
    inline const BuffEntry *FindBuffById(const RPC::BuffId &id) {
        for (const auto &buff : g_Buffs) {
            if (buff.id == id) {
                return &buff;
            }
        }
        return FindCustomBuffById(id);
    }

    /** The name a script would recognise, or empty for a definition this build has no row for. */
    inline std::string_view BuffNameOf(const RPC::BuffId &id) {
        const BuffEntry *entry = FindBuffById(id);
        return entry != nullptr ? entry->name : std::string_view();
    }
} // namespace KCDC::Shared::Game
